sp_widget.css:
.metric-card{

height:220px;

background:white;

border-radius:28px;

padding:34px;

box-shadow:
0 24px 60px
rgba(
7,
17,
44,
.08
);

transition:.25s;

position:relative;

overflow:hidden;

}



.metric-card:hover{

transform:
translateY(-8px);

}



.icon{

width:78px;

height:78px;

border-radius:22px;

display:flex;

align-items:center;

justify-content:center;

font-size:34px;

background:
linear-gradient(
135deg,
#2F63FF,
#5B85FF
);

}



.number{

margin-top:24px;

font-size:64px;

font-weight:900;

color:#061844;

}



.title{

font-size:26px;

font-weight:800;

margin-top:8px;

color:#2D3F72;

}



.sub{

margin-top:8px;

font-size:16px;

color:#8A97B7;

}



.metric-card::after{

content:'';

position:absolute;

right:-60px;

bottom:-60px;

width:180px;

height:180px;

border-radius:50%;

background:
rgba(
47,
99,
255,
.06
);

}

sp_widget.script:
(function(){

data.total=0;

var gr=
new GlideAggregate(
'x_1902481_employ_0_employee'
);

gr.addAggregate(
'COUNT'
);

gr.query();

if(gr.next()){

data.total=
gr.getAggregate(
'COUNT'
);

}

})();
